# Generated by rex-statusline init bash. PS0 requires Bash 4.4+.
case $- in *i*) ;; *) return 0 ;; esac
[ -n "${REX_SESSION:-}" ] && [ -n "${REX_BLOCK:-}" ] || return 0
[ -z "${SSH_CONNECTION:-}" ] && [ -z "${SSH_TTY:-}" ] || return 0
[ "${_bsp_initialized:-}" != bash ] || return 0
if (( BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 4) )); then
  printf '%s\n' 'rex-statusline: Bash 4.4+ is required for prompt integration' >&2
  return 1
fi
_bsp_executable=@EXECUTABLE@
_bsp_started=-1
_bsp_duration_ms=0
_bsp_empty=

_bsp_precmd() {
  local last_status=$? now running_jobs
  if [ -z "${SSH_CONNECTION:-}" ] && [ -z "${SSH_TTY:-}" ]; then
    if [ -n "${EPOCHREALTIME:-}" ]; then
      now=${EPOCHREALTIME/./}
    else
      now=$((SECONDS * 1000000))
    fi
    if (( _bsp_started >= 0 )); then
      _bsp_duration_ms=$(((now - _bsp_started) / 1000))
      _bsp_started=-1
    fi
    running_jobs=$(jobs -p | wc -l)
    command "$_bsp_executable" publish --source local --owner "$$" \
      --cwd "$PWD" --jobs "$((running_jobs))" --exit-code "$last_status" \
      --duration-ms "$_bsp_duration_ms" >/dev/null 2>&1
  fi
  return "$last_status"
}
# An empty substring records the start time without printing or using DEBUG.
# PS0 must defer expansion until the command starts.
# shellcheck disable=SC2016
if [ -n "${EPOCHREALTIME:-}" ]; then
  PS0='${_bsp_empty:$((_bsp_started=${EPOCHREALTIME/./})):0}'"${PS0:-}"
else
  PS0='${_bsp_empty:$((_bsp_started=SECONDS*1000000)):0}'"${PS0:-}"
fi
# Keep existing prompt commands, including array entries, and their exit status.
# shellcheck disable=SC2178,SC2128
if [[ $(declare -p PROMPT_COMMAND 2>/dev/null) == 'declare -a '* ]]; then
  PROMPT_COMMAND=(_bsp_precmd "${PROMPT_COMMAND[@]}")
else
  PROMPT_COMMAND="_bsp_precmd${PROMPT_COMMAND:+; $PROMPT_COMMAND}"
fi
_bsp_initialized=bash
